// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public { c = new Reentrance(); }

    // fuzz parameters: deposit amount and an attacker private key (so we can produce an address)
    function testFuzz_property(uint256 depositAmount, uint256 attackerKey) public {
        vm.assume(depositAmount <= VALUE_CAP);
        attackerKey = bound(attackerKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep depositAmount in a reasonable range but wide enough to include non-zero
        depositAmount = bound(depositAmount, 0, 1 ether);
        // attackerKey -> attacker address
        address attacker = vm.addr(uint256(attackerKey));

        // deploy a reentrant attacker that will call back into c.withdrawBalance once
        Attacker a = new Attacker(c);

        // fund attacker so it can deposit
        vm.deal(address(a), depositAmount);

        // attacker makes a deposit by calling addToBalance()
        vm.prank(address(a));
        if (depositAmount > 0) {
            // call payable addToBalance
            bool ok; try c.addToBalance{value: depositAmount}() { ok = true; } catch { ok = false; }
            require(ok, "deposit failed");
        }

        // Precondition: recorded balance equals depositAmount
        uint256 before = c.getBalance(address(a));
        // allow zero deposits too; the invariant should hold for all inputs
        // Now attacker triggers withdrawBalance which will re-enter during the external call
        // The attacker will re-enter exactly once (inside its receive)
        bool ok;
        vm.prank(address(a));
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the top-level withdrawBalance call returns, for the correct contract the stored balance must be zero
        // (the reference resets the stored balance before making the external call). The mutant that zeros after the
        // external call can be re-entered and may leave the stored balance non-zero.
        assertTrue(c.getBalance(address(a)) == 0, "balance not zero after withdraw (mutant likely present)");
    }
}

// Attacker contract: records a flag to re-enter exactly once during receive()
contract Attacker {
    Reentrance public c;
    bool private __entered;

    constructor(Reentrance _c) {
        c = _c;
        __entered = false;
    }

    // receive will be invoked when C sends Ether via low-level call
    receive() external payable {
        // re-enter exactly once: call withdrawBalance again while original withdrawBalance is still in its external call
        if (!__entered) {
            __entered = true;
            // re-enter: call withdrawBalance on C
            c.withdrawBalance();
        }
    }
}
